package com.sami.app.sales.document;
import com.sami.app.common.domain.BaseEntity; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Entity @Table(name="sales_documents") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor public class SalesDocument extends BaseEntity {
 @Column(name="tenant_id",nullable=false) Long tenantId; @Column(name="company_id",nullable=false) Long companyId; @Column(name="branch_id",nullable=false) Long branchId; @Enumerated(EnumType.STRING) @Column(name="document_type",nullable=false) SalesDocumentType documentType; @Column(name="document_number",nullable=false) String documentNumber; @Column(name="customer_id",nullable=false) Long customerId; @Column(name="contact_id",nullable=false) Long contactId; @Enumerated(EnumType.STRING) @Column(nullable=false) SalesDocumentStatus status; @Column(nullable=false) @Builder.Default String currency="IRR"; @Column(nullable=false) @Builder.Default BigDecimal subtotal=BigDecimal.ZERO; @Column(name="discount_total",nullable=false) @Builder.Default BigDecimal discountTotal=BigDecimal.ZERO; @Column(name="final_amount",nullable=false) @Builder.Default BigDecimal finalAmount=BigDecimal.ZERO; @Column(length=2000) String notes; @Column(name="issued_at") Instant issuedAt; @Column(name="cancelled_at") Instant cancelledAt; @Column(name="expired_at") Instant expiredAt; @Column(name="created_by") Long createdBy; @Column(name="created_by_email") String createdByEmail; @OneToMany(mappedBy="document",cascade=CascadeType.ALL,orphanRemoval=true) @Builder.Default List<SalesDocumentLine> lines=new ArrayList<>(); }
